 for j,k,b,x,y,n,n0,staff in ns:
  if not P or (j,k,b)!=P[-1][:3] or x-P[-1][3]>(1.0 if i>=4 else 2.9):G.append([]);P.append((j,k,b,x,y))
  G[-1].append((n,n0,x,y,staff))
