def align(i,start=0,end=1e4,bar1=1,bar2=1000,reverse=False,minstep=0,maxstep=300,pen=.010):
 g,p,m=groups(i);js=[j for j,x in enumerate(p) if bar1<=x[2]<=bar2];g=[g[j] for j in js];p=[p[j] for j in js];
 d=load(i);keep=(d['t']>=start)&(d['t']<end);ts=d['t'][keep];a0=d['a'][keep];o0=d['o'][keep];
 w=np.percentile(a0,85,axis=0)*.28+np.max(a0,axis=0)*.025+.06
 a=maximum_filter1d(a0,size=5,axis=0);o=maximum_filter1d(o0,size=5,axis=0)
 # relative salience of onsets and simultaneous fundamental presence
 aa=np.log1p(a/w);oo=np.log1p(o/w*2.8)
 # encourage all tones; keep substitute error hedge low
 em=[]
 for gn in g:
  ns=sorted(set((n,n0) for n,n0,*_ in gn));vv=[]
  for n,n0 in ns:
   ix=np.clip(n-21,0,87);val=(.45*aa[:,ix]+.9*oo[:,ix]);
   if n0==n:
    for e in [-1,1]:
     j=np.clip(n+e-21,0,87);val=np.maximum(val,.69*(.45*aa[:,j]+.9*oo[:,j])-.10)
   vv.append(val)
  q=np.mean(vv,axis=0);q-=.40*np.percentile(q,94);em.append(q)
 if reverse:em=em[::-1];em=[v[::-1] for v in em]
 T=len(ts);prev=np.zeros(T,np.float32); bps=np.empty((len(p),T),np.int32);grid=np.arange(T,dtype=np.int32);
 for j,e in enumerate(em):
  if not j:prev=e.copy();bps[j]=0;continue
  cur=np.zeros(T,dtype=np.float32)-1e8; bp=np.zeros(T,np.int32)
  # exact max-plus over plausible inter-onset intervals, with cheap coarse candidates for long gaps
  for k in list(range(minstep,min(90,maxstep)))+list(range(max(minstep,90),maxstep,3)):
   if k>=T:break
   v=prev[:T-k]-max(0,k-9)*pen-(.67 if k==0 else .22 if k<4 else 0)
   dst=cur[k:];where=v>dst; np.copyto(dst,v,where=where);np.copyto(bp[k:],grid[:T-k],where=where)
  prev=e+cur;bps[j]=bp
 idx=np.argmax(prev);path=[]
 for j in range(len(p)-1,-1,-1):path.append(idx);idx=bps[j,idx]
 path=path[::-1];
 if reverse:path=[T-1-q for q in path[::-1]]
 return [(round(float(ts[z]),3),*q,gn) for z,q,gn in zip(path,p,g)]

if __name__=='__main__':
 i=int(sys.argv[1]);data=align(i,*[float(a) for a in sys.argv[2:4]],*[int(a) for a in sys.argv[4:6]]) if len(sys.argv)>2 else align(i);j=0
